WITH rc AS (SELECT * FROM recipes WHERE capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged')), (SELECT mapFromArrays(groupArray(id), groupArray(name)) FROM (SELECT id, argMax(name, release) AS name FROM item_names GROUP BY id)) AS inames, lv AS (SELECT crystal_id, ingredients, arraySort(groupArray(CAST((craft, attempts, skill_ups, level_min, min_n, level_max, max_n), 'Tuple(craft Int32, attempts UInt64, skill_ups UInt64, level_min Nullable(Int32), min_n UInt64, level_max Nullable(Int32), max_n UInt64)'))) AS levels FROM (SELECT crystal_id, ingredients, l.craft AS craft, sum(l.attempts) AS attempts, sum(l.skill_ups) AS skill_ups, max(l.level_min) AS level_min, sum(l.min_n) AS min_n, min(l.level_max) AS level_max, sum(l.max_n) AS max_n FROM rc ARRAY JOIN levels AS l GROUP BY crystal_id, ingredients, craft) GROUP BY crystal_id, ingredients), g AS (SELECT crystal_id, ingredients, max(desynth) AS desynth, sum(attempts) AS attempts, sum(nq) AS nq, sum(hq1) AS hq1, sum(hq2) AS hq2, sum(hq3) AS hq3, sum(breaks) AS breaks, min(nq_item_id) AS nq_item, min(nq_count) AS nq_count, min(hq1_item_id) AS hq1_item, min(hq1_count) AS hq1_count, min(hq2_item_id) AS hq2_item, min(hq2_count) AS hq2_count, min(hq3_item_id) AS hq3_item, min(hq3_count) AS hq3_count, uniq(capture_id) AS captures, max(ts_ms) AS last, argMax(capture_id, ts_ms) AS last_capture, argMax(idx, ts_ms) AS last_idx, max(release) AS release FROM rc GROUP BY crystal_id, ingredients) SELECT g.crystal_id AS crystal, nullIf(inames[g.crystal_id], '') AS crystal_name, arrayMap(x -> CAST((x.1, x.2, nullIf(inames[x.1], '')), 'Tuple(item Int32, quantity Int32, name Nullable(String))'), g.ingredients) AS ingredients, g.desynth AS desynth, g.attempts AS attempts, g.nq AS nq, g.hq1 AS hq1, g.hq2 AS hq2, g.hq3 AS hq3, g.breaks AS breaks, g.nq_item AS nq_item, nullIf(inames[assumeNotNull(g.nq_item)], '') AS nq_name, g.nq_count AS nq_count, g.hq1_item AS hq1_item, nullIf(inames[assumeNotNull(g.hq1_item)], '') AS hq1_name, g.hq1_count AS hq1_count, g.hq2_item AS hq2_item, nullIf(inames[assumeNotNull(g.hq2_item)], '') AS hq2_name, g.hq2_count AS hq2_count, g.hq3_item AS hq3_item, nullIf(inames[assumeNotNull(g.hq3_item)], '') AS hq3_name, g.hq3_count AS hq3_count, lv.levels AS levels, g.captures AS captures, g.last AS last, g.last_capture AS last_capture, g.last_idx AS last_idx, g.release AS release FROM g LEFT JOIN lv ON lv.crystal_id = g.crystal_id AND lv.ingredients = g.ingredients ORDER BY attempts DESC, crystal, g.ingredients
